import json
import math
from pathlib import Path


def _reject_constant(value):
    raise ValueError("non-finite JSON literal: %s" % value)


def _parse_float(text):
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("non-finite JSON number: %s" % text)
    return value


def load_payload(path):
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except OSError as exc:
        raise ValueError("cannot read payload file %s: %s" % (p, exc)) from exc
    try:
        obj = json.loads(text, parse_constant=_reject_constant, parse_float=_parse_float)
    except ValueError as exc:
        raise ValueError("invalid JSON payload %s: %s" % (p, exc)) from exc
    if not isinstance(obj, (dict, list)):
        raise ValueError("payload top-level must be an object or an array")
    return obj

import copy

TOLERANCE = 1e-9


def _require_dict(value, what):
    if not isinstance(value, dict):
        raise ValueError("%s must be an object" % what)
    return value


def _require_list(value, what):
    if not isinstance(value, list):
        raise ValueError("%s must be an array" % what)
    return value


def _require_str(value, what):
    if not isinstance(value, str) or not value.strip():
        raise ValueError("%s must be a non-empty string" % what)
    return value


def _require_bool(value, what):
    if not isinstance(value, bool):
        raise ValueError("%s must be a boolean" % what)
    return value


def _require_number(value, what):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("%s must be a number" % what)
    if value != value or value in (float("inf"), float("-inf")):
        raise ValueError("%s must be a finite number" % what)
    return value


def _require_nonneg_number(value, what):
    _require_number(value, what)
    if value < 0:
        raise ValueError("%s must be non-negative" % what)
    return value


def _require_field(obj, key, what):
    if key not in obj:
        raise ValueError("%s is missing required field %r" % (what, key))
    return obj[key]


def _check_finite(value, what="value"):
    if isinstance(value, bool):
        return
    if isinstance(value, float):
        if value != value or value in (float("inf"), float("-inf")):
            raise ValueError("%s contains a non-finite number" % what)
        return
    if isinstance(value, dict):
        for v in value.values():
            _check_finite(v, what)
        return
    if isinstance(value, list):
        for v in value:
            _check_finite(v, what)


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


def _begin(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    _require_str(contract.get("name"), "contract name")
    inputs = contract.get("inputs")
    if not isinstance(inputs, list):
        raise ValueError("contract inputs must be an array")
    if len(inputs) != len(payloads):
        raise ValueError("payload count must match contract inputs")
    for p in payloads:
        _check_finite(p, "payload")


def _parse_classes(value, what):
    classes = _require_list(value, what)
    seen = set()
    for i, c in enumerate(classes):
        if not isinstance(c, str) or not c.strip():
            raise ValueError("%s[%d] must be a non-empty string" % (what, i))
        if c in seen:
            raise ValueError("%s[%d] duplicates class %r" % (what, i, c))
        seen.add(c)
    return classes, seen


def _is_permestation(mclasses, classes, class_set):
    return (
        len(mclasses) == len(classes)
        and len(set(mclasses)) == len(mclasses)
        and set(mclasses) <= class_set
    )


def transform(payloads, contract):
    _begin(payloads, contract)
    data = _require_dict(_unwrap(payloads[0]), "fit input")
    classes, class_set = _parse_classes(
        _require_field(data, "classes", "fit input"), "classes"
    )
    sample_weight = _require_list(
        _require_field(data, "sample_weight", "fit input"), "sample_weight"
    )
    for i, w in enumerate(sample_weight):
        _require_nonneg_number(w, "sample_weight[%d]" % i)
    sample_count = len(sample_weight)
    members = _require_list(_require_field(data, "members", "fit input"), "members")
    ids = set()
    active = []
    total_weight = 0
    for i, m in enumerate(members):
        m = _require_dict(m, "members[%d]" % i)
        mid = _require_str(
            _require_field(m, "id", "members[%d]" % i), "members[%d].id" % i
        )
        if mid in ids:
            raise ValueError("duplicate member id %r" % mid)
        ids.add(mid)
        is_active = _require_bool(
            _require_field(m, "active", "members[%d]" % i),
            "members[%d].active" % i,
        )
        if not is_active:
            continue
        weight = _require_nonneg_number(
            _require_field(m, "weight", "members[%d]" % i),
            "members[%d].weight" % i,
        )
        preds = _require_list(
            _require_field(m, "predictions", "members[%d]" % i),
            "members[%d].predictions" % i,
        )
        if len(preds) != sample_count:
            raise ValueError(
                "members[%d].predictions length must equal the sample count" % i
            )
        for j, p in enumerate(preds):
            if not isinstance(p, str) or p not in class_set:
                raise ValueError(
                    "members[%d].predictions[%d] is not a known class" % (i, j)
                )
        mclasses = _require_list(
            _require_field(m, "classes", "members[%d]" % i),
            "members[%d].classes" % i,
        )
        if not _is_permestation(mclasses, classes, class_set):
            raise ValueError(
                "members[%d].classes must be a permutation of the global classes" % i
            )
        probs = _require_list(
            _require_field(m, "probabilities", "members[%d]" % i),
            "members[%d].probabilities" % i,
        )
        if len(probs) != sample_count:
            raise ValueError(
                "members[%d].probabilities must have one row per sample" % i
            )
        for r, row in enumerate(probs):
            row = _require_list(row, "members[%d].probabilities[%d]" % (i, r))
            if len(row) != len(mclasses):
                raise ValueError(
                    "members[%d].probabilities[%d] length must match the member classes"
                    % (i, r)
                )
            row_sum = 0
            for v in row:
                _require_number(v, "members[%d].probabilities[%d] value" % (i, r))
                if v < 0:
                    raise ValueError(
                        "members[%d].probabilities[%d] values must be non-negative"
                        % (i, r)
                    )
                row_sum = row_sum + v
            if abs(row_sum - 1.0) > TOLERANCE:
                raise ValueError(
                    "members[%d].probabilities[%d] must sum to 1" % (i, r)
                )
        total_weight = total_weight + weight
        active.append(m)
    if not active:
        raise ValueError("at least one active member is required")
    if not total_weight > 0:
        raise ValueError("active member weights must sum to a positive value")
    out_members = []
    for m in active:
        cm = copy.deepcopy(m)
        cm["fit_weight"] = copy.deepcopy(sample_weight)
        out_members.append(cm)
    result = {
        "classes": copy.deepcopy(classes),
        "sample_count": sample_count,
        "members": out_members,
    }
    return {"name": contract["name"], "result": result}

