import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
INTEGRATE = ROOT / "integrate.py"
FINAL_REPORT = ROOT / "final_report.py"


def _load_contracts():
    components = {}
    for cp in sorted(ROOT.rglob("contract.json")):
        rel = cp.relative_to(ROOT)
        if "outputs" in rel.parts:
            continue
        try:
            contract = json.loads(cp.read_text(encoding="utf-8"))
        except ValueError as exc:
            raise ValueError("invalid contract %s: %s" % (cp, exc)) from exc
        if not isinstance(contract, dict):
            raise ValueError("contract %s must be an object" % cp)
        name = contract.get("name")
        if not isinstance(name, str) or not name.strip():
            raise ValueError("contract %s has an invalid name" % cp)
        if name in components:
            raise ValueError("duplicate component name %r" % name)
        inputs = contract.get("inputs")
        if not isinstance(inputs, list) or not all(
            isinstance(p, str) and p.strip() for p in inputs
        ):
            raise ValueError("contract %s has invalid inputs" % cp)
        output = contract.get("output")
        if not isinstance(output, str) or not output.strip():
            raise ValueError("contract %s has an invalid output" % cp)
        components[name] = (cp, contract)
    if not components:
        raise ValueError("no contracts found")
    return components


def _topological_order(components):
    producers = {}
    for name, (_cp, contract) in components.items():
        output = contract["output"]
        if output in producers:
            raise ValueError(
                "output %s produced by both %r and %r"
                % (output, producers[output], name)
            )
        producers[output] = name
    deps = {}
    for name, (_cp, contract) in components.items():
        d = set()
        for p in contract["inputs"]:
            if p == contract["output"]:
                raise ValueError("component %r depends on its own output" % name)
            producer = producers.get(p)
            if producer is not None and producer != name:
                d.add(producer)
        deps[name] = d
    order = []
    done = set()
    pending = set(deps)
    while pending:
        ready = sorted(n for n in pending if deps[n] <= done)
        if not ready:
            raise ValueError(
                "dependency cycle among components: %s" % ", ".join(sorted(pending))
            )
        for n in ready:
            order.append(n)
            done.add(n)
            pending.discard(n)
    return order, producers


def _check_inputs_available(components, producers):
    for name, (_cp, contract) in components.items():
        for p in contract["inputs"]:
            if p in producers:
                continue
            if not (ROOT / p).is_file():
                raise ValueError(
                    "missing dependency %s for component %r" % (p, name)
                )


def _clear_stale_outputs(components):
    stale = [contract["output"] for _cp, contract in components.values()]
    stale += ["outputs/core_manifest.json", "outputs/final_report.json"]
    for rel in stale:
        f = ROOT / rel
        if f.is_symlink() or f.is_file():
            f.unlink()


def main():
    components = _load_contracts()
    order, producers = _topological_order(components)
    _check_inputs_available(components, producers)
    _clear_stale_outputs(components)
    for name in order:
        cp, _contract = components[name]
        script = cp.with_name("render.py")
        if not script.is_file():
            raise ValueError("missing render.py for component %r" % name)
        subprocess.run([sys.executable, str(script)], cwd=ROOT, check=True)
    if not INTEGRATE.is_file():
        raise ValueError("missing integrate.py")
    subprocess.run([sys.executable, str(INTEGRATE)], cwd=ROOT, check=True)
    if not FINAL_REPORT.is_file():
        raise ValueError("missing final_report.py")
    subprocess.run([sys.executable, str(FINAL_REPORT)], cwd=ROOT, check=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
CORE_PATH = ROOT / "outputs" / "core_manifest.json"
REPORT_PATH = ROOT / "outputs" / "final_report.json"
TITLE = "可关闭成员的硬/软加权投票"
FALSE_KEYS = ("complete", "checkout", "committed", "ok")
NONEMPTY_KEYS = ("unavailable", "missing", "conflicts", "unreachable")


def _attention(components):
    names = set()
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            names.add(name)
        for key in FALSE_KEYS:
            if result.get(key) is False:
                names.add(name)
        for key in NONEMPTY_KEYS:
            value = result.get(key)
            if value is None or isinstance(value, bool):
                continue
            if isinstance(value, (list, dict, str, bytes, tuple)):
                if len(value) > 0:
                    names.add(name)
            elif value:
                names.add(name)
    return sorted(names)


def build_report(core):
    if not isinstance(core, dict) or set(core) != {"components"}:
        raise ValueError("core manifest must contain exactly 'components'")
    components = core["components"]
    if not isinstance(components, dict):
        raise ValueError("core components must be an object")
    blob = json.dumps(
        core, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    digest = hashlib.sha256(blob).hexdigest()
    return {
        "title": TITLE,
        "component_count": len(components),
        "sha256": digest,
        "attention": _attention(components),
    }


def main():
    try:
        core = json.loads(CORE_PATH.read_text(encoding="utf-8"))
    except OSError as exc:
        raise ValueError("missing core manifest: %s" % exc) from exc
    except ValueError as exc:
        raise ValueError("invalid core manifest: %s" % exc) from exc
    report = build_report(core)
    REPORT_PATH.parent.mkdir(parents=True, exist_ok=True)
    REPORT_PATH.write_text(
        json.dumps(
            report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False
        )
        + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
